    blush:       ["nessuno", "leggero", "intenso", "abbronzato"],
    colBlush:    ["#ff8fa3", "#ff6b6b", "#f4a261", "#e599f7", "#d9480f", "#c9856b"],
    guance:    ["no", "leggere", "rosse", "lentiggini"],
