        if (s && s.classList) {
          s.classList.add("g-" + g.id);
          if (!s.classList.contains("sg-scura") && (g.tema === "oro" || s.classList.contains("oro"))) { s.classList.add("oro"); if (g.tema === "oro") s.classList.add("sg-dal-gioco"); }
          else { s.classList.remove("oro"); s._gioco = true; }
        }
