    var c = el("div", { class: "tb-p" + (mio ? " mia" : "") + (p.vince ? " decisa" : ""), "data-k": p.k });
    function nome(id) { return el("span", { class: "tb-n" + (p.vince === id ? " vince" : (p.vince ? " perde" : "")), text: nomeElim(E, id) }); }
