    var velo = crea("div", "rg-velo sgs-ruota"); velo.appendChild(scheda);
    velo.setAttribute("data-vince", String(vince));

    var fermo = false, finito = false, tPoi = null, ang = 0, tacca = 0, tSuono = -1e9;
